     6  Elf32_Sym const *PackLinuxElf32::elf_lookup(char const *name) const
     7  {
     8      if (hashtab && dynsym && dynstr) {
     9          unsigned const n_bucket = get_te32(&hashtab[0]);
    10          unsigned const *const buckets = &hashtab[2];
    11          unsigned const *const chains = &buckets[n_bucket];
    12          // Find the end of DT_HASH and DT_DYNSYM. Perhaps elf_find_table_size()
    13          // depends on too many valid input values?
    14          void const *l_hash = nullptr, *l_sym = nullptr;
    15          for (unsigned j = 0; j < DT_NUM; ++j) {
    16              void const *const ptr = dt_offsets[j] + (char const *)file_image.getVoidPtr();
    17              if (!l_hash && hashtab == ptr) {
    18                  l_hash = dt_offsets[1+ j] + (char const *)file_image.getVoidPtr();
    19              }
    20              if (!l_sym && dynsym == ptr) {
    21                  l_sym = dt_offsets[1+ j] + (char const *)file_image.getVoidPtr();
    22              }
    23              if (l_sym && l_hash)
    24                  break;  // found both
    25              if (this->file_size == (off_t)dt_offsets[j])
    26                  break;  // end sentinel
    27          }
    28          if (n_bucket) {
    29              unsigned const m = elf_hash(name) % n_bucket;
    30              unsigned n_visit = 0;
    31              unsigned si;
    32              if (l_hash <= &buckets[m])
    33                  throwCantPack("bad DT_HASH %u", m);
    34              for (si= get_te32(&buckets[m]); si; si = get_te32(&chains[si])) {
    35                  if (l_sym <= &dynsym[si])
    36                      throwCantPack("bad DT_HASH chain %d\n", si);
    37                  char const *const p= get_dynsym_name(si, (unsigned)-1);
    38                  if (p && 0==strcmp(name, p))
    39                      return &dynsym[si];
    40                  if (l_sym <= &dynsym[n_visit++])
    41                      throwCantPack("circular DT_HASH chain %d\n", si);
    42              }
    43          }
    44      }
    45      if (gashtab && dynsym && dynstr) {
    46          unsigned const n_bucket = get_te32(&gashtab[0]);
    47          unsigned const symbias  = get_te32(&gashtab[1]);
    48          unsigned const n_bitmask = get_te32(&gashtab[2]);
    49          unsigned const gnu_shift = get_te32(&gashtab[3]);
    50          unsigned const *const bitmask = &gashtab[4];
    51          unsigned const *const buckets = &bitmask[n_bitmask];
    52          unsigned const *const hasharr = &buckets[n_bucket];
    53          if (31 < gnu_shift) {
    54              throwCantPack("bad gnu_shift %#x", gnu_shift);
    55          }
    56          if ((file_size + file_image) <= (void const *)hasharr) {
    57              throwCantPack("bad n_bucket %#x\n", n_bucket);
    58          }
    59          if (!n_bitmask
    60          || (unsigned)(file_size - ((char const *)bitmask - (char const *)(void const *)file_image))
    61                  <= sizeof(unsigned)*n_bitmask ) {
    62              throwCantPack("bad n_bitmask %#x\n", n_bitmask);
    63          }
    64          if (n_bucket) { // -rust-musl can have "empty" hashtab
    65              unsigned const h = gnu_hash(name);
    66              unsigned const hbit1 = 037& h;
    67              unsigned const hbit2 = 037& (h>>gnu_shift);
    68              unsigned const w = get_te32(&bitmask[(n_bitmask -1) & (h>>5)]);
    69
    70              if (1& (w>>hbit1) & (w>>hbit2)) {
    71                  unsigned const hhead = get_te32(&buckets[h % n_bucket]);
    72                  if (symnum_max <= hhead || (hhead && hhead < symbias)) {
    73                      throwCantPack("bad DT_GNU_HASH symnum_max{%#x} <= buckets[%d]{%#x} < symbias{%#x}\n",
    74                              symnum_max, h % n_bucket, hhead, symbias);
    75                  }
    76                  if (hhead) {
    77                      Elf32_Sym const *dsp = &dynsym[hhead];
    78                      unsigned const *hp = &hasharr[hhead - symbias];
    79                      unsigned k;
    80                      do {
    81                          if (gashend <= hp) {
    82                              throwCantPack("bad DT_GNU_HASH[%#x]  head=%u",
    83                                  (unsigned)(hp - hasharr), hhead);
    84                          }
    85                          k = get_te32(hp);
    86                          if (0==((h ^ k)>>1)) {
    87                              unsigned const st_name = get_te32(&dsp->st_name);
    88                              char const *const p = get_str_name(st_name, (unsigned)-1);
    89                              if (0==strcmp(name, p)) {
    90                                  return dsp;
    91                              }
    92                          }
    93                      } while (++dsp, ++hp, 0==(1u& k));
    94                  }
    95              }
    96          }
    97      }
    98      // 2021-12-25  FIXME: Some Rust programs use
    99      //    (1==n_bucket && 0==buckets[0] && 1==n_bitmask && 0==bitmask[0])
   100      // to minimize space in DT_GNU_HASH. This causes the fancy lookup to fail.
   101      // Is a fallback to linear search assumed?
   102      // 2022-03-12  Some Rust programs have 0==n_bucket.
   103      return nullptr;
   104
   105  }
